import json
x=json.load(open('run_trace/galaxy_tool_schema/tool_response.json'))
# recursively print relevant names and metadata

def walk(o,path=''):
 if isinstance(o,dict):
  p=path+('/'+str(o.get('name')) if o.get('name') else '')
  if o.get('name') in {'countsFile','rep_factorName','rep_factorLevel','lfc_shrinkage_type','header','prefilter'}:
   print(p, {k:o.get(k) for k in ('model_class','type','multiple','default','value','optional')})
  for k,v in o.items():
   if k in ('inputs','cases'): walk(v,p+'/'+k)
 elif isinstance(o,list):
  for i,v in enumerate(o): walk(v,path)
walk(x.get('inputs',[]))
PY"

